"""Every rounding rule of meterbill, in one place."""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _units(exact: Fraction, step: Decimal, method: str) -> int:
    """The magnitude of `exact` in whole steps, rounded by `method`."""
    ratio = abs(exact) / Fraction(step)
    whole, rest = divmod(ratio.numerator, ratio.denominator)
    twice = 2 * rest
    if method == HALF_UP and twice >= ratio.denominator:
        whole += 1
    elif method == HALF_EVEN and (twice > ratio.denominator or (twice == ratio.denominator and whole % 2 == 1)):
        whole += 1
    return whole


def _build(negative: bool, units: int, step: Decimal) -> Decimal:
    sign, digits, exponent = step.as_tuple()
    coefficient = int("".join(map(str, digits))) * units
    return Decimal((1 if negative else 0, tuple(int(c) for c in str(coefficient)), exponent))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    units = _units(Fraction(value), step, method)
    return _build(value.is_signed(), units, step)


def _zero_sum_sign(first: tuple, second: tuple) -> bool:
    """Sign of a zero sum of two signed quantities (negative, units)."""
    return first[1] == 0 and second[1] == 0 and first[0] and second[0]


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    for amount in amounts:
        _check(amount, step, HALF_UP)
    amounts = list(amounts)
    parts = [(amount.is_signed(), _units(Fraction(amount), step, DOWN)) for amount in amounts]
    total = sum((Fraction(amount) for amount in amounts), Fraction(0))
    whole = (total < 0, _units(total, step, HALF_UP))
    signed_parts = sum((-units if negative else units for negative, units in parts), 0)
    signed_whole = -whole[1] if whole[0] else whole[1]
    rest_units = signed_whole - signed_parts
    rest = (rest_units < 0, abs(rest_units))
    if rest_units == 0 and not (whole[1] == 0 and whole[0] and signed_parts == 0):
        rest = (False, 0)
    for index in range(len(parts) - 1, -1, -1):
        if amounts[index] != 0:
            current = parts[index]
            summed = (-current[1] if current[0] else current[1]) + rest_units
            if summed == 0:
                parts[index] = (_zero_sum_sign(current, rest), 0)
            else:
                parts[index] = (summed < 0, abs(summed))
            break
    return [_build(negative, units, step) for negative, units in parts]


def legacy_cents(value: float, places: int = 2) -> float:
    if isinstance(places, bool) or not isinstance(places, int) or places < 0:
        raise ValueError("places must be a non-negative integer")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(places, bool) or not isinstance(places, int) or places < 0:
        raise ValueError("places must be a non-negative integer")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half to even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    rounded = round_amount(value, Decimal((0, (1,), -places)), method)
    return format(rounded, "f")
